export type BarbinSex = "unknown" | "male" | "female";

export const BARBIN_TARGET_EVENT = "useCardToTargeted" as const;
export const BARBIN_SKILL_TARGET_EVENTS = ["useSkill", "logSkillBegin"] as const;

export function isDesignationSkillTarget(
	isOtherPlayer: boolean,
	isListedTarget: boolean,
	isViewAsSkill: boolean,
	hasSkillName: boolean
): boolean {
	return isOtherPlayer && isListedTarget && !isViewAsSkill && hasSkillName;
}

export interface RoundUseRecord {
	roundNumber: number;
	count: number;
}

export interface InterventionOutcome {
	sex: "male" | "female";
	kuGained: number;
}

export type DeclarationSex = "male" | "female";

export interface DeclarationDecisionInput {
	isFriendly: boolean;
	maleMarks: number;
	femaleMarks: number;
	maleImmediateEffect: number;
	femaleImmediateEffect: number;
	tieSex: DeclarationSex;
}

export interface RejectionDecisionInput {
	ku: number;
	maleMarks: number;
	femaleMarks: number;
	declaredSex: DeclarationSex;
	immediateEffectDifference: number;
	hasNonCriticalDiscard: boolean;
	lowestNonCriticalDiscardValue?: number;
	rejectionMilestoneBenefit?: number;
	handcardsAfterDiscard: number;
	hp: number;
}

export interface DesignationRejectionOutcome {
	rejected: boolean;
	kuGained: number;
}

const IMMEDIATE_EFFECT_THRESHOLD = 0.5;

export function getRoundUseCount(record: RoundUseRecord | undefined, roundNumber: number): number {
	return record?.roundNumber === roundNumber ? record.count : 0;
}

export function canUseWithinRound(record: RoundUseRecord | undefined, roundNumber: number, limit: number): boolean {
	return getRoundUseCount(record, roundNumber) < limit;
}

export function recordRoundUse(record: RoundUseRecord | undefined, roundNumber: number): RoundUseRecord {
	return {
		roundNumber,
		count: getRoundUseCount(record, roundNumber) + 1,
	};
}

export function getInterventionOutcome(maleMarks: number, femaleMarks: number, tieSex: "male" | "female"): InterventionOutcome {
	const male = Math.max(0, Math.trunc(maleMarks));
	const female = Math.max(0, Math.trunc(femaleMarks));
	return {
		sex: male === female ? tieSex : male > female ? "male" : "female",
		kuGained: Math.min(male, female) * 2,
	};
}

export function getCriticalDesignationKu(maleMarks: number, femaleMarks: number, declaredSex: DeclarationSex): number | undefined {
	const male = Math.max(0, Math.trunc(maleMarks));
	const female = Math.max(0, Math.trunc(femaleMarks));
	if (male + female !== 2) return undefined;
	const nextMale = male + (declaredSex === "male" ? 1 : 0);
	const nextFemale = female + (declaredSex === "female" ? 1 : 0);
	return Math.min(nextMale, nextFemale) * 2;
}

export function canGainDesignationMark(maleMarks: number, femaleMarks: number): boolean {
	return Math.max(0, Math.trunc(maleMarks)) + Math.max(0, Math.trunc(femaleMarks)) < 3;
}

export function getYushenDrawCount(sex: BarbinSex, kuAfterRemoval: number): number {
	if (sex !== "unknown") return 0;
	return Math.trunc(kuAfterRemoval) > 0 ? 1 : 0;
}

export function chooseDesignationDeclaration(input: DeclarationDecisionInput): DeclarationSex {
	const immediateDifference = input.maleImmediateEffect - input.femaleImmediateEffect;
	if (Math.abs(immediateDifference) > IMMEDIATE_EFFECT_THRESHOLD) {
		if (input.isFriendly) return immediateDifference > 0 ? "male" : "female";
		return immediateDifference > 0 ? "female" : "male";
	}

	if (input.maleMarks === input.femaleMarks) return input.tieSex;
	if (input.isFriendly) return input.maleMarks < input.femaleMarks ? "male" : "female";
	return input.maleMarks < input.femaleMarks ? "female" : "male";
}

export function shouldRejectDesignation(input: RejectionDecisionInput): boolean {
	if (!input.hasNonCriticalDiscard) return false;

	if (input.immediateEffectDifference < -IMMEDIATE_EFFECT_THRESHOLD) return true;
	if (input.immediateEffectDifference > IMMEDIATE_EFFECT_THRESHOLD) return false;

	const total = input.maleMarks + input.femaleMarks;
	if (input.ku >= 3) return total === 2;
	const lowestValue = input.lowestNonCriticalDiscardValue ?? 0;
	if (input.ku === 2) {
		const milestoneBenefit = Math.max(0, input.rejectionMilestoneBenefit ?? 0);
		const threshold = 4 + milestoneBenefit + (total === 2 ? 1 : 0);
		return lowestValue <= threshold;
	}

	const ordinaryDiscardAllowed = input.handcardsAfterDiscard >= input.hp;
	const nextMale = input.maleMarks + (input.declaredSex === "male" ? 1 : 0);
	const nextFemale = input.femaleMarks + (input.declaredSex === "female" ? 1 : 0);
	if (total === 2) {
		return ordinaryDiscardAllowed && lowestValue <= 4 && (nextMale === 3 || nextFemale === 3);
	}

	if (input.maleMarks === input.femaleMarks) return false;
	const declaredCurrentMajority =
		(input.maleMarks > input.femaleMarks && input.declaredSex === "male") ||
		(input.femaleMarks > input.maleMarks && input.declaredSex === "female");
	return ordinaryDiscardAllowed && lowestValue <= 4 && declaredCurrentMajority;
}

export function getDesignationRejectionOutcome(confirmed: boolean, discardedCardCount: number): DesignationRejectionOutcome {
	const rejected = confirmed && discardedCardCount > 0;
	return { rejected, kuGained: rejected ? 1 : 0 };
}

export function shouldTriggerRejectionMilestone(kuBefore: number, kuGained: number, hasTriggered: boolean): boolean {
	if (hasTriggered) return false;
	const before = Math.max(0, Math.trunc(kuBefore));
	const gained = Math.max(0, Math.trunc(kuGained));
	return gained > 0 && before < 3 && before + gained >= 3;
}

export function shouldCancelWithYushen(confirmed: boolean, ku: number): boolean {
	return confirmed && ku > 0;
}
